/* Учебный прототип. Серверная аутентификация, транзакции и печать здесь не реализованы. */
(() => {
 'use strict';
 const KEY='electronic-queue-rr2-v1';
 const labels={waiting:'Ожидание',called:'Вызван',in_service:'Обслуживание',completed:'Завершён',no_show:'Неявка',cancelled:'Отменён'};
 const transitions={waiting:['called','cancelled'],called:['in_service','no_show'],in_service:['completed'],completed:[],no_show:[],cancelled:[]};
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const uuid=()=>crypto.randomUUID();
 const day=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow'}).format(d);
 const fmt=d=>d?new Date(d).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
 let currentView='visitor', selectedWindow=1, selectedTicket=null, toastTimer;
 function seed(){
  const now=Date.now(), t=(m)=>new Date(now-m*60000).toISOString();
  const services=[{id:1,prefix:'A',name:'Приём документов',active:true},{id:2,prefix:'B',name:'Выдача документов',active:true},{id:3,prefix:'C',name:'Консультация',active:true}];
  const tickets=[
   {id:uuid(),service_id:1,seq_no:1,number:'A-001',status:'completed',created_at:t(34),called_at:t(26),started_at:t(25),finished_at:t(18),window_id:1},
   {id:uuid(),service_id:2,seq_no:1,number:'B-001',status:'completed',created_at:t(29),called_at:t(22),started_at:t(21),finished_at:t(16),window_id:2},
   {id:uuid(),service_id:3,seq_no:1,number:'C-001',status:'no_show',created_at:t(25),called_at:t(18),finished_at:t(16),window_id:2},
   {id:uuid(),service_id:1,seq_no:2,number:'A-002',status:'waiting',created_at:t(12)},
   {id:uuid(),service_id:2,seq_no:2,number:'B-002',status:'waiting',created_at:t(9)},
   {id:uuid(),service_id:3,seq_no:2,number:'C-002',status:'waiting',created_at:t(7)}
  ].map(t=>({...t,business_date:day(new Date(t.created_at))}));
  return {version:1,services,windows:[{id:1,name:'Окно 1',services:[1],operator:'Оператор 1'},{id:2,name:'Окно 2',services:[2,3],operator:'Оператор 2'}],tickets,events:[]};
 }
 function load(){try{const s=JSON.parse(localStorage.getItem(KEY)); if(s?.version===1&&Array.isArray(s.tickets)&&Array.isArray(s.services)&&Array.isArray(s.windows))return s;}catch{}return seed();}
 let state=load();
 const service=id=>state.services.find(s=>s.id===id);
 const win=()=>state.windows.find(w=>w.id===selectedWindow);
 const todayTickets=()=>state.tickets.filter(t=>t.business_date===day(new Date()));
 const active=()=>todayTickets().find(t=>t.window_id===selectedWindow&&['called','in_service'].includes(t.status));
 const waiting=(ids)=>todayTickets().filter(t=>t.status==='waiting'&&(!ids||ids.includes(t.service_id))).sort((a,b)=>a.created_at.localeCompare(b.created_at)||a.id.localeCompare(b.id));
 function notify(text){const el=document.querySelector('#notice');el.textContent=text;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4200);}
 function save(){localStorage.setItem(KEY,JSON.stringify(state));render();}
 function event(t,from,to){state.events.push({id:uuid(),ticket_id:t.id,from_status:from,to_status:to,occurred_at:new Date().toISOString(),window_id:t.window_id||null});}
 function move(t,to){if(!transitions[t.status]?.includes(to)){notify('Этот переход состояния недоступен');return false;}if(to==='no_show'&&Date.now()-new Date(t.called_at).getTime()<120000){notify('Неявку можно отметить через 2 минуты после вызова');return false;}const from=t.status;t.status=to;const now=new Date().toISOString();if(to==='called')t.called_at=now;if(to==='in_service')t.started_at=now;if(['completed','no_show','cancelled'].includes(to))t.finished_at=now;event(t,from,to);return true;}
 function issue(sid){const s=service(sid);if(!s?.active){notify('Выдача талонов на эту услугу приостановлена');return;}const date=day(new Date()),seq=Math.max(0,...state.tickets.filter(t=>t.service_id===sid&&t.business_date===date).map(t=>t.seq_no))+1;const t={id:uuid(),service_id:sid,seq_no:seq,number:s.prefix+'-'+String(seq).padStart(3,'0'),business_date:date,status:'waiting',created_at:new Date().toISOString()};state.tickets.push(t);event(t,null,'waiting');selectedTicket=t.id;save();notify('Талон выдан. Следите за информационным табло');}
 function callNext(){if(active()){notify('Завершите работу с текущим талоном');return;}const t=waiting(win().services)[0];if(!t){notify('Нет ожидающих талонов для выбранного окна');return;}t.window_id=selectedWindow;move(t,'called');save();notify('Вызван талон '+t.number);}
 function heading(h,p){return `<h1>${h}</h1><p class="lead">${p}</p>`;}
 function rows(tickets){return tickets.map(t=>`<tr><td><b>${esc(t.number)}</b></td><td>${esc(service(t.service_id)?.name||'Услуга недоступна')}</td><td>${fmt(t.created_at)}</td><td><span class="tag">${labels[t.status]}</span></td></tr>`).join('');}
 function table(tickets){return tickets.length?`<div class="table-wrap"><table><thead><tr><th>Талон</th><th>Услуга</th><th>Выдан</th><th>Состояние</th></tr></thead><tbody>${rows(tickets)}</tbody></table></div>`:'<div class="empty">Талонов пока нет</div>';}
 function visitor(){const t=state.tickets.find(t=>t.id===selectedTicket);return heading('Получить талон','Выберите услугу. Обслуживание ведётся в порядке выдачи талонов для каждой услуги.')+`<div class="grid">${state.services.map(s=>`<button class="service" data-issue="${s.id}" ${s.active?'':'disabled'}><span class="prefix">${esc(s.prefix)}</span><b>${esc(s.name)}</b><small>${s.active?'Ожидают: '+waiting([s.id]).length:'Выдача приостановлена'}</small></button>`).join('')}</div>`+(t?`<div class="panel" style="margin-top:24px"><div class="two"><div><span class="tag">Ваш талон</span><div class="ticket-number">${esc(t.number)}</div><b>${esc(service(t.service_id).name)}</b></div><div><p>Состояние <strong>${labels[t.status]}</strong></p><p>Время выдачи ${fmt(t.created_at)}</p><p class="muted">Ожидайте вызова на табло. Номер окна появится после вызова.</p>${t.status==='waiting'?`<button class="secondary" data-cancel="${t.id}">Отменить мой талон</button>`:''}</div></div></div>`:'<p class="legend">Талон содержит номер и время выдачи. ФИО посетителя не запрашивается.</p>');}
 function display(){const calls=todayTickets().filter(t=>['called','in_service'].includes(t.status));return heading('Информационное табло','Найдите номер своего талона и пройдите к указанному окну.')+`<div class="grid">${state.windows.map(w=>{const t=calls.find(t=>t.window_id===w.id);return `<div class="panel"><h2>${esc(w.name)}</h2><div class="board-number">${t?esc(t.number):'—'}</div><span class="tag">${t?labels[t.status]:'Ожидание вызова'}</span><p class="muted">${t?esc(service(t.service_id).name):'Следите за обновлением табло'}</p></div>`;}).join('')}</div><div class="panel"><h2>Ожидают вызова</h2>${table(waiting())}</div>`;}
 function operator(){const t=active();return heading('Рабочее место оператора','Вызовите следующего посетителя и отметьте результат обслуживания.')+`<label for="window">Рабочее окно</label><select id="window">${state.windows.map(w=>`<option value="${w.id}" ${w.id===selectedWindow?'selected':''}>${esc(w.name)} · ${esc(w.operator)}</option>`).join('')}</select><div class="two" style="margin-top:22px"><div class="panel"><h2>Текущий талон</h2>${t?`<div class="ticket-number">${esc(t.number)}</div><span class="tag">${labels[t.status]}</span><p>${esc(service(t.service_id).name)}</p><div class="actions">${t.status==='called'?'<button data-action="start">Начать обслуживание</button><button class="secondary" data-action="repeat">Повторить вызов</button><button class="danger" data-action="no_show">Неявка</button>':'<button data-action="complete">Завершить обслуживание</button>'}</div>`:'<div class="empty">Текущего талона нет</div>'}<div class="actions"><button data-action="next" ${t?'disabled':''}>Вызвать следующего</button></div></div><div class="panel"><h2>Доступная очередь · ${waiting(win().services).length}</h2>${table(waiting(win().services))}<p class="legend">Услуги окна: ${win().services.map(id=>esc(service(id).name)).join(', ')}.</p></div></div>`;}
 function admin(){return heading('Администрирование','Управление доступностью услуг и просмотром истории очереди.')+`<div class="panel"><h2>Услуги</h2><table><thead><tr><th>Код</th><th>Наименование</th><th>Выдача талонов</th><th>Действие</th></tr></thead><tbody>${state.services.map(s=>`<tr><td>${esc(s.prefix)}</td><td>${esc(s.name)}</td><td>${s.active?'Открыта':'Приостановлена'}</td><td><button class="secondary" data-toggle="${s.id}">${s.active?'Приостановить':'Возобновить'}</button></td></tr>`).join('')}</tbody></table><p class="legend">Приостановление закрывает новые выдачи. Ранее выданные талоны продолжают обслуживаться. История сохраняется.</p></div><div class="panel"><h2>История талонов за сегодня</h2>${table(todayTickets().slice().reverse())}</div>`;}
 function stats(){const ts=todayTickets(),done=ts.filter(t=>t.status==='completed'),wait=done.map(t=>(new Date(t.started_at)-new Date(t.created_at))/60000),dur=done.map(t=>(new Date(t.finished_at)-new Date(t.started_at))/60000),avg=a=>a.length?(a.reduce((a,b)=>a+b,0)/a.length).toFixed(1):'—';return heading('Статистика','Показатели рассчитаны по демонстрационным талонам за текущую дату Москвы.')+`<div class="grid"><div class="panel"><div class="kpi-label">Выдано талонов</div><div class="kpi">${ts.length}</div></div><div class="panel"><div class="kpi-label">Завершено обслуживаний</div><div class="kpi">${done.length}</div></div><div class="panel"><div class="kpi-label">Среднее ожидание до начала, мин</div><div class="kpi">${avg(wait)}</div></div></div><div class="panel"><h2>Результаты по услугам</h2><table><thead><tr><th>Услуга</th><th>Ожидают</th><th>Завершены</th><th>Неявка</th><th>Отменены</th></tr></thead><tbody>${state.services.map(s=>{const a=ts.filter(t=>t.service_id===s.id);return `<tr><td>${esc(s.name)}</td>${['waiting','completed','no_show','cancelled'].map(k=>`<td>${a.filter(t=>t.status===k).length}</td>`).join('')}</tr>`;}).join('')}</tbody></table><p>Средняя длительность обслуживания <strong>${avg(dur)} мин</strong>.</p><p class="legend">Выборка среднего ожидания включает только завершённые обслуживания. Неявки и отмены учитываются отдельно. Эти данные не являются результатами реального внедрения.</p><button id="csv" class="secondary">Выгрузить обезличенный CSV</button></div>`;}
 const views={visitor,display,operator,admin,stats};
 function render(){document.querySelector('#main').innerHTML=views[currentView]();document.querySelectorAll('[data-view]').forEach(b=>{b.removeAttribute('aria-current');if(b.dataset.view===currentView)b.setAttribute('aria-current','page');});const noShow=document.querySelector('[data-action="no_show"]');if(noShow){const t=active();noShow.disabled=!!t&&Date.now()-new Date(t.called_at).getTime()<120000;noShow.title=noShow.disabled?'Доступно через 2 минуты после вызова':'';}}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
  if(b.dataset.view){currentView=b.dataset.view;render();document.querySelector('#main').focus();}
  if(b.dataset.issue)issue(Number(b.dataset.issue));
  if(b.dataset.cancel){const t=state.tickets.find(t=>t.id===b.dataset.cancel);if(t&&move(t,'cancelled')){save();notify('Талон отменён');}}
  if(b.dataset.toggle){const s=service(Number(b.dataset.toggle));s.active=!s.active;save();notify('Доступность услуги обновлена');}
  if(b.dataset.action){const a=b.dataset.action,t=active();if(a==='next')callNext();else if(t){if(a==='repeat'){event(t,'called','called');save();notify('Повторно вызван талон '+t.number);}else {const to={start:'in_service',complete:'completed',no_show:'no_show'}[a];if(move(t,to)){save();notify('Состояние талона обновлено');}}}}
  if(b.id==='reset'&&confirm('Заменить текущие демонстрационные данные исходным примером?')){state=seed();selectedTicket=null;save();notify('Демонстрационный пример восстановлен');}
  if(b.id==='csv'){const lines=['date;number;service;status;created_at;started_at;finished_at',...todayTickets().map(t=>[t.business_date,t.number,service(t.service_id).prefix,t.status,t.created_at,t.started_at||'',t.finished_at||''].join(';'))];const u=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='queue-'+day(new Date())+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 });
 document.addEventListener('change',e=>{if(e.target.id==='window'){selectedWindow=Number(e.target.value);render();}});
 window.addEventListener('storage',e=>{if(e.key===KEY){state=load();render();}});
 setInterval(()=>{document.querySelector('#clock').textContent=new Date().toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})+' МСК';const noShow=document.querySelector('[data-action="no_show"]');if(noShow){const t=active();noShow.disabled=!!t&&Date.now()-new Date(t.called_at).getTime()<120000;noShow.title=noShow.disabled?'Доступно через 2 минуты после вызова':'';}},1000);
 save();
})();
